update FIN_PRODUCT_ADD
set /** FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR},*/
    /** CARRYOVER_FREQ = #{carryoverFreq,jdbcType=VARCHAR}, */
    PUR_SPEED = #{purSpeed,jdbcType=DECIMAL},
    RED_SPEED = #{redSpeed,jdbcType=DECIMAL},
    IS_COMPOUND_INT = #{isCompoundInt,jdbcType=VARCHAR}
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

update FIN_PRODUCT_TYPE
set TYPE_1 = #{type1,jdbcType=VARCHAR}
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

update FIN_PRODUCT
set FINPROD_ABBR = #{finprodAbbr,jdbcType=VARCHAR},
    FINPROD_NAME = #{finprodName,jdbcType=VARCHAR},
    PROFIT_TYPE = #{profitType,jdbcType=VARCHAR},
    FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR},
    BLN_AREA = #{blnArea,jdbcType=VARCHAR},
    TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR},
    CALENDAR_ID = #{calendarId,jdbcType=VARCHAR},
    IDATE = #{idate,jdbcType=DATE},
    CAPI_INCOME_FEATURE = #{capiIncomeFeature,jdbcType=VARCHAR}
where FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
and CCY = #{ccy,jdbcType=VARCHAR}
and FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
